function member(id: string, role: 'owner' | 'member', label: string | null) {
  const p = SAMPLE_PEOPLE[id];
  return { id, displayName: p.name, timeZone: p.zone, avatar: { definition: p.avatar, version: 1 }, role, label, city: p.city };
}

