function local(iso: string, zone: string) {
  const d = new Date(iso);
  const time = new Intl.DateTimeFormat('en-GB', { timeZone: zone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
  const date = new Intl.DateTimeFormat('en-CA', { timeZone: zone }).format(d);
  const abbreviation = new Intl.DateTimeFormat('en-US', { timeZone: zone, timeZoneName: 'short' }).formatToParts(d).find((p) => p.type === 'timeZoneName')?.value ?? zone;
  return { time, date, zone, abbreviation };
}

